corporate_design.toad_component_blueprint:
canvas {
  size: 920px 580px;
  fill: #F0FDFA;
  font-family: "Inter, sans-serif";
}

>mint = #0D9488;
>lightTeal = #CCFBF1;
>slate = #0F172A;

rect #appCard {
  at: center of canvas;
  size: 820px 480px;
  fill: #FFFFFF;
  radius: 16px;
}

text #appHeader {
  at: top left of #appCard offset 36px 36px;
  content: "CURA TELEHEALTH // ARZTSPRECHSTUNDE IN 5 MINUTEN";
  font-size: 13px;
  font-weight: 700;
  color: >mint;
}

text #appTitle {
  at: below #appHeader offset 14px;
  content: "Gesundheit ohne Wartezimmer.";
  font-size: 34px;
  font-weight: 700;
  color: >slate;
}

rect #prescriptionPill {
  at: below #appTitle offset 24px;
  size: 220px 36px;
  fill: >lightTeal;
  radius: 9999px;
}

text #pillText {
  at: center of #prescriptionPill;
  content: "✔ OFFIZIELLES E-REZEPT";
  font-size: 11px;
  font-weight: 700;
  color: >mint;
}
